const postback = $input.first().json.postback || '';
const senderId = $input.first().json.senderId;

const parts = postback.split('|');
const productId = parts[0] || null;
const size = parts[1] || null;
let addOn = parts[2] || null;
if (addOn?.startsWith('ADD_')) addOn = addOn.slice(4);

const isBite = productId?.startsWith('BK-');

if (!productId) {
  return {
    json: {
      error: 'Invalid product selection',
      senderId
    }
  };
}

return {
  json: {
    productId,
    size: size === 'NONE' ? null : size,
    addOn: addOn === 'NONE' ? null : addOn,
    isBite,
    senderId,
    needsDbFetch: true
  }
};

const postback = $json.latestPostback || $json.postback;
const productId = postback.replace('ADD_', '');

return [{ json: { productId } }];

const product = $input.first().json;
const senderId = $('Listen').first().json.senderId;
const priceFormat = p => (p ? `₱${p}` : '');

const isBite = product.ProductID && product.ProductID.startsWith('BK-');

if (isBite) {
  // For bites, create a postback similar to the drink format but with NONE for size and add-on
  return [{
    json: {
      sendSizeButtons: false,
      sizeSelected: false,
      message: `Selected: ${product.Name} (${priceFormat(product.BasePrice)}). Adding to cart...`,
      senderId,
      isBitesSelected: true,
      // Create postback in the same format as drinks but with NONE values
      postback: `${product.ProductID}|NONE|NONE`,
      type: "postback"
    }
  }];
}

const sizes = Array.isArray(product.Sizes) ? product.Sizes : [];

if (sizes.length === 0) {
  return [{
    json: {
      sendSizeButtons: false,
      sizeSelected: false,
      message: `Selected: ${product.Name} (${priceFormat(product.BasePrice)}). Added to cart!`,
      senderId
    }
  }];
}

const buttons = sizes.map(s => ({
  type: "postback",
  title: `${s.Size} - ${priceFormat(s.BasePrice)}`,
  payload: `${product.ProductID}|${s.Size}`
}));

return [{
  json: {
    sendSizeButtons: true,
    sizeSelected: false,
    recipient_id: senderId,
    message: `Choose a size for your ${product.Name}:`,
    buttons
  }
}];

