    : `https://via.placeholder.com/300x200?text=${encodeURIComponent(item.Name)}`,
  subtitle: item.description || "Tasty bite-sized treats",
  buttons: [
    {
      type: "postback",
      title: "Add to Cart",
      payload: `ADD_${item.ProductID}`
    }
  ]
}));

elements.push({
  title: "Main Menu",
  image_url: "https://via.placeholder.com/300x200?text=Main+Menu",
  subtitle: "Return to main menu",
  buttons: [
    {
      type: "postback",
      title: "Go Back",
      payload: "REVIEW_MENU"
    }
  ]
});

const responsePayload = {
  messaging_type: "RESPONSE",
  recipient: { id: senderId },
  message: {
    attachment: {
      type: "template",
      payload: {
        template_type: "generic",
        elements: elements
      }
    }
  }
};

return [{ json: responsePayload }];

const postback = $input.first().json.postback || '';
const parts = postback.split('|');

return {
  json: {
    ...$json,
    isCompleteOrder: parts.length === 3 && parts[1] !== 'NONE',
    isBitesOrder: parts.length === 3 && parts[0].startsWith('BK-')
  }
};

const productData = $input.all().find(item => item.json.ProductID)?.json;
const addOnData = $input.all().find(item => item.json.AddOnID)?.json;
const senderId = $input.first().json.senderId;

let requiredIngredients = {};
let directItems = {};

if (productData?.Ingredients && productData.Ingredients.length > 0) {
  productData.Ingredients.forEach(ingredientId => {
    if (!requiredIngredients[ingredientId]) {
      requiredIngredients[ingredientId] = 0;
    }
    requiredIngredients[ingredientId] += 1;
  });
}

if (productData?.ProductID?.startsWith('BK-') && productData.Quantity !== undefined) {
  directItems[productData.ProductID] = {
    required: 1,
    available: productData.Quantity,
    name: productData.Name
  };
}

if (addOnData?.Quantity !== undefined) {
  directItems[addOnData.AddOnID] = {
    required: 1,
    available: addOnData.Quantity,
    name: addOnData.Name
  };
}

return [
  {
    json: {
      productData,
      addOnData,
      requiredIngredients,
      directItems,
      needsIngredientCheck: Object.keys(requiredIngredients).length > 0,
      needsDirectCheck: Object.keys(directItems).length > 0,
      senderId,
      _stockCheckData: true
    }
  }
];

const allInputs = $input.all();
const stockData = allInputs[0].json.stockCheckData;
const senderId = $('extract values').first().json.senderId;

const inventoryData = allInputs.filter(item => item.json.IngredientID || item.json.AddOnID);

const { productData, addOnData, directItems, requiredIngredients } = stockData;

let errors = [];
let warnings = [];

if (productData && (!productData.IsEnabled || !productData.available)) {
  errors.push(`${productData.Name} is currently unavailable`);
}

if (addOnData && !addOnData.IsEnabled) {
  errors.push(`${addOnData.Name} add-on is currently unavailable`);
}

if (Object.keys(requiredIngredients).length > 0) {
  Object.entries(requiredIngredients).forEach(([ingredientId, required]) => {
    const ingredient = inventoryData.find(inv => inv.json.IngredientID === ingredientId);
    if (!ingredient) {
      errors.push(`Ingredient ${ingredientId} not found in inventory`);
    } else if (!ingredient.json.IsEnabled) {
      errors.push(`Ingredient ${ingredient.json.Name} is currently disabled`);
    } else if (ingredient.json.Quantity < required) {
      errors.push(`Insufficient ${ingredient.json.Name} stock (need: ${required}, have: ${ingredient.json.Quantity})`);
    } else if (ingredient.json.Quantity <= 5) {
      warnings.push(`Low stock warning: ${ingredient.json.Name} (${ingredient.json.Quantity} remaining)`);
    }
  });
}

Object.entries(directItems || {}).forEach(([itemId, itemInfo]) => {
  const addon = inventoryData.find(inv => inv.json.AddOnID === itemId);
  if (addon) {
    if (!addon.json.IsEnabled) {
      errors.push(`${addon.json.Name} add-on is currently disabled`);
    } else if (addon.json.Quantity < itemInfo.required) {
      errors.push(`Insufficient ${addon.json.Name} stock (need: ${itemInfo.required}, have: ${addon.json.Quantity})`);
    } else if (addon.json.Quantity <= 3) {
      warnings.push(`Low stock: ${addon.json.Name} (${addon.json.Quantity} remaining)`);
    }
  }
});

return {
  json: {
    isValid: errors.length === 0,
    errors,
    warnings,
    productData,
    addOnData,
    senderId: senderId,
    canProceed: errors.length === 0
  }
};

const currentData = $input.all();
const stockCheckData = $('Check Inventory Stock').first().json;

return currentData.map(item => ({
  json: {
    ...item.json,
    stockCheckData: stockCheckData
  }
}));

const allInputs = $input.all();
const validationResult = allInputs[0].json;

if (!validationResult.isValid) {
  return {
    json: {
      success: false,
      message: "Cannot add to cart due to validation errors",
      errors: validationResult.errors,
      warnings: validationResult.warnings
    }
  };
}

const { productData, addOnData } = validationResult;
const stockData = allInputs[0].json.stockCheckData || validationResult.stockCheckData;

const cartItem = {
  productId: productData.ProductID,
  productName: productData.Name,
  category: productData.Category,
  basePrice: productData.Sizes[0].BasePrice,
  size: "16oz",
  quantity: 1,
  addOns: addOnData ? [{
    addOnId: addOnData.AddOnID,
    addOnName: addOnData.Name,
    addOnPrice: addOnData.BasePrice,
    quantity: 1
  }] : [],
  totalPrice: productData.Sizes[0].BasePrice + (addOnData ? addOnData.BasePrice : 0),
  timestamp: new Date().toISOString(),
  userId: $('Listen').first().json.senderId
};

return {
  json: {
    success: true,
    message: "Item successfully added to cart",
    cartItem: cartItem,
    warnings: validationResult.warnings
  }
};

const senderId = $input.first().json.senderId

if (!senderId) {
  return [{ json: { error: "No sender ID found, cannot retrieve cart." } }];
}

return [{ json: { senderId } }];

const cartDoc = $input.first().json;
const userCart = Array.isArray(cartDoc.items) ? cartDoc.items : [];
let messageText;

if (!userCart.length) {
  messageText = "Your cart is empty.";
} else {
  messageText = "🛒 Your Cart:\n";
  userCart.forEach((item, idx) => {
    messageText += `\n${idx + 1}. ${item.productName} (${item.size})\nQty: ${item.quantity}`;
    if (item.addOns && item.addOns.length) {
      messageText += `\nAdd-ons: ${item.addOns.join(", ")}`;
    }
    messageText += `\nPrice: ₱${item.price}\n`;
  });
  const total = userCart.reduce((sum, item) => sum + item.price, 0);
  messageText += `\nTotal: ₱${total}`;
}

return {
  json: {
    recipient_id: cartDoc.userId || $('Listen').first().json.senderId,
    message: messageText
  }
};

const userId = $('Listen').first().json.senderId;
const cartItem = $input.first().json.cartItem;

return {
  json: {
    userId: userId,
    cartItem: cartItem
  }
};

const data = $('Upsert Prepare').first().json;
const now = new Date().toISOString();

return {
  json: {
    userId: data.userId,
    items: [data.cartItem], // Create a new items array with the first item
    createdAt: now,
    updatedAt: now
  }
};

const newItemData = $('Upsert Prepare').first().json;


const existingCart = $('Add to Cart DB').first().json;

const updatedItems = [...existingCart.items, newItemData.cartItem];

return {
  json: {
    userId: existingCart.userId,
    items: updatedItems,
    updatedAt: new Date().toISOString()
  }
};

